with ranked as (select * from web_events qualify rank() over (partition by session_id, page order by duration_sec desc nulls first) = 1), enriched as (select e.id, e.session_id, e.page, e.event_time, e.duration_sec, d.country, d.device from ranked e left join sessions d on e.session_id = d.id where d.browser in ('Firefox', 'Edge', 'Safari')), metrics as (select *, count(duration_sec) over (partition by page order by duration_sec, id rows between 3 preceding and current row) as last4_count_duration_sec, avg(duration_sec) over (partition by page order by duration_sec, id rows between 3 preceding and current row) as last4_avg_duration_sec, max(duration_sec) over (partition by page order by duration_sec, id rows between 3 preceding and current row) as last4_max_duration_sec, avg(duration_sec) over (partition by country) as country_avg_duration_sec from enriched), with_windows as (select *, sum(last4_count_duration_sec) over (partition by device order by last4_max_duration_sec, id rows between unbounded preceding and current row) as cumulative_last4_count_duration_sec, avg(last4_avg_duration_sec) over (partition by device) as device_avg_last4_avg_duration_sec, avg(country_avg_duration_sec) over (partition by page, device order by country_avg_duration_sec, id rows between 6 preceding and 1 preceding) as country_avg_duration_sec_avg_6_prior from metrics), flagged as (select *, case when event_time - lag(event_time) over (partition by page order by event_time, id) > interval '90' day then 1 else 0 end as session_start_flag from with_windows), islands as (select id, session_id, page, event_time, last4_avg_duration_sec, country_avg_duration_sec, cumulative_last4_count_duration_sec, country_avg_duration_sec_avg_6_prior, sum(session_start_flag) over (partition by page order by event_time, id rows between unbounded preceding and current row) as session_no from flagged) select p.browser, s.page, count(*) as cnt, sum(s.last4_avg_duration_sec) as total_last4_avg_duration_sec from islands s left join sessions p on s.session_id = p.id group by grouping sets ((p.browser, s.page), (p.browser), ());
